#!/usr/bin/env python3
"""Embed fonts/font.ttf into a C header so the app is one self-contained binary.

Usage: python3 tools/embed_font.py fonts/font.ttf build/font_data.h
"""

import sys
from pathlib import Path


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print(__doc__.strip(), file=sys.stderr)
        return 2
    source = Path(argv[1])
    target = Path(argv[2])
    data = source.read_bytes()
    target.parent.mkdir(parents=True, exist_ok=True)

    lines = [
        "/* Generated by tools/embed_font.py from %s -- do not edit. */" % source.name,
        "#ifndef DIMOS_FONT_DATA_H",
        "#define DIMOS_FONT_DATA_H",
        "",
        "static const unsigned char font_ttf[] = {",
    ]
    for offset in range(0, len(data), 16):
        chunk = ", ".join("0x%02X" % byte for byte in data[offset : offset + 16])
        lines.append("    %s," % chunk)
    lines += [
        "};",
        "",
        "static const unsigned int font_ttf_size = %du;" % len(data),
        "",
        "#endif",
        "",
    ]
    target.write_text("\n".join(lines))
    print("embedded %d bytes of %s into %s" % (len(data), source, target))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
